            flex-direction: column;
            gap: clamp(6px, 1vh, 10px);
            z-index: 100;
            list-style: none;
        }
        .nav-dot {
            width: 7px; height: 7px;
            border-radius: 50%;
            background: var(--text-muted);
            cursor: pointer;
            transition: all 0.3s ease;
            border: none;
        }
        .nav-dot.active {
            background: var(--accent);
            transform: scale(1.5);
            box-shadow: 0 0 8px var(--accent-glow);
        }

        /* ===========================================
           SLIDE 1 — TITLE
           =========================================== */
